private boolean tryToLocateSignature(final long minDistanceFromEnd,
                                    final long maxDistanceFromEnd,
                                    final byte[] sig) throws IOException {
    final long archiveSize = archive.size();
    final long stopSearching = Math.max(0, archiveSize - maxDistanceFromEnd);
    long position = archiveSize - minDistanceFromEnd;

    if (position < stopSearching || position < 0) {
        return false;
    }

    final int bufferSize = 4096;
    final ByteBuffer buffer = ByteBuffer.allocate(bufferSize + sig.length - 1);

    while (position >= stopSearching) {
        final long blockStart = Math.max(stopSearching, position - bufferSize + 1);
        final int blockLength = (int) (position - blockStart + 1);
        final int bytesToRead = (int) Math.min(blockLength + sig.length - 1,
                                               archiveSize - blockStart);

        buffer.clear();
        buffer.limit(bytesToRead);
        archive.position(blockStart);
        IOUtils.readFully(archive, buffer);
        final byte[] data = buffer.array();

        for (int i = blockLength - 1; i >= 0; i--) {
            boolean matches = i + sig.length <= bytesToRead;
            for (int j = 0; matches && j < sig.length; j++) {
                matches = data[i + j] == sig[j];
            }
            if (matches) {
                archive.position(blockStart + i);
                return true;
            }
        }

        if (blockStart == stopSearching) {
            break;
        }
        position = blockStart - 1;
    }
    return false;
}

